<template>
  <div class="login-page">
    <!-- 3D Sci-Fi Particle Background -->
    <ParticleBackground
      :particle-count="250"
      :speed="0.4"
      :opacity="0.75"
      :particle-size="3.8"
      :spread-x="500"
      :spread-y="500"
      :spread-z="350"
      :connection-distance="100"
      :line-opacity="0.1"
      :drift-speed="0.06"
      color1="#00f0ff"
      color2="#b847ff"
      :show-core="true"
      :core-particle-count="600"
      :core-radius="50"
      :core-size="5"
      core-color="#ffffff"
      :orbit-count="3"
      :orbit-radius="140"
      orbit-color="#00f0ff"
      :orbit-opacity="0.85"
      :orbit-speed="0.6"
      :show-beams="true"
      :beam-count="80"
      :beam-length="320"
      beam-color="#00f0ff"
      :show-pulse="true"
      pulse-color="#00f0ff"
      :pulse-max-radius="260"
      :show-wireframe="true"
      wireframe-color="#00e5ff"
      :wireframe-opacity="0.3"
    />

    <!-- Login Card -->
    <div class="login-card">
      <div class="login-header">
        <div class="card-dot"></div>
        <div class="card-title">社团场地管理系统</div>
        <div class="card-sub">高校社团活动 · 场地调度一站管理</div>
      </div>
      <el-form ref="form" :model="form" :rules="rules" @submit.native.prevent="submit">
        <el-form-item prop="username">
          <el-input v-model="form.username" size="small" placeholder="用户名" prefix-icon="el-icon-user" />
        </el-form-item>
        <el-form-item prop="password">
          <el-input v-model="form.password" size="small" type="password" placeholder="密码" prefix-icon="el-icon-lock" show-password @keyup.enter.native="submit" />
        </el-form-item>
        <el-form-item>
          <el-button type="primary" size="small" class="login-btn" @click="submit" :loading="loading">
            登 录
          </el-button>
        </el-form-item>
        <div class="link-register">
          没有账号？<router-link to="/register">立即注册</router-link>
        </div>
      </el-form>
    </div>
  </div>
</template>

<script>
import request from '@/api'
import ParticleBackground from '@/components/ParticleBackground.vue'

export default {
  name: 'Login',
  components: { ParticleBackground },
  data() {
    return {
      form: { username: '', password: '' },
      rules: {
        username: [{ required: true, message: '请输入用户名', trigger: 'blur' }],
        password: [{ required: true, message: '请输入密码', trigger: 'blur' }]
      },
      loading: false
    }
  },
  methods: {
    async submit() {
      try {
        await this.$refs.form.validate()
      } catch { return }
      this.loading = true
      try {
        const res = await request.post('/user/login', this.form)
        if (res.code === 200) {
          localStorage.setItem('user', JSON.stringify(res.data))
          localStorage.setItem('role', res.data.role || 'user')
          this.$message.success('登录成功')
          this.$router.push(this.$route.query.redirect || '/')
        } else {
          this.$message.error(res.message || '登录失败')
        }
      } catch {
        this.$message.error('登录失败')
      } finally {
        this.loading = false
      }
    },
  }
}
</script>

